/* Contenido de «Comunicación Efectiva, Oratoria y Redacción Profesional». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-comunicacion",{"l":{"c-comunicacion-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar, con claridad.</b> Este es un <b>curso libre de capacitación</b>. Al terminarlo recibes una <b>constancia de Instituto Mara</b>, que <b>no</b> es un documento oficial de la SEP ni una certificación de CONOCER. Su valor está en lo que vas a poder hacer mejor desde mañana: hablar en una junta, escribir un correo claro o pedir lo que necesitas sin pelearte con nadie."},{"tipo":"texto","texto":"Cada vez que te comunicas pasa lo mismo: un <b>emisor</b> (quien habla o escribe) convierte una idea en un <b>mensaje</b>, lo manda por un <b>canal</b> (en persona, llamada, correo, WhatsApp) y un <b>receptor</b> lo interpreta según su contexto. Después viene la <b>retroalimentación</b>: la respuesta que te dice si entendió. El problema es que lo que tú quisiste decir y lo que el otro entendió casi nunca son idénticos. Comunicar bien es reducir esa distancia."},{"tipo":"tabla","titulo":"Los elementos, con un ejemplo de oficina","encabezados":["Elemento","Qué es","Ejemplo"],"filas":[["Emisor","Quien tiene la idea y la expresa","Karla, supervisora de almacén"],["Mensaje","Lo que se dice o escribe","«Necesito el inventario para el viernes»"],["Canal","El medio por el que viaja","Un audio de WhatsApp a las 9 de la noche"],["Receptor","Quien recibe e interpreta","Luis, auxiliar, que lo escucha al día siguiente"],["Contexto","La situación que rodea al mensaje","Es fin de mes y hay dos inventarios distintos"],["Retroalimentación","La respuesta que confirma o corrige","«¿El de refacciones o el de producto terminado?»"]],"nota":"Sin retroalimentación no sabes si te entendieron: solo supones."},{"tipo":"texto","texto":"Todo lo que distorsiona el mensaje se llama <b>ruido</b>. No es solo el ruido físico. Hay ruido <b>físico</b> (el camión que pasa, la mala señal en la videollamada), <b>semántico</b> (palabras que el otro no entiende o entiende distinto, como «urgente» o «al rato»), <b>psicológico</b> (el enojo, el cansancio, los prejuicios sobre quien habla) y <b>técnico o del canal</b> (un correo que cae en correo no deseado, un audio de siete minutos que nadie escucha completo)."},{"tipo":"relacionar","rotulo":"Relaciona el caso con el tipo de ruido","pares":[["La junta es junto a la cocina y la licuadora no para","Ruido físico"],["Tu jefe dice «para ahorita» y tú entiendes «cuando puedas»","Ruido semántico"],["No escuchas bien la propuesta porque viene del área con la que siempre chocas","Ruido psicológico"],["Mandaste las indicaciones en un audio de seis minutos","Ruido del canal"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La retroalimentación sirve para…","ops":["Repetir el mensaje más fuerte","Terminar la conversación rápido","Confirmar que el mensaje se entendió como querías"],"correcta":2,"explica":"Una pregunta de regreso o un «entonces quedamos en…» evita muchos malentendidos."},{"p":"«Lo necesito para mañana temprano» es un mensaje con riesgo de ruido…","ops":["Técnico","Semántico: «temprano» significa algo distinto para cada quien","Físico"],"correcta":1,"explica":"Mejor di la hora: «para mañana a las 9:00»."},{"p":"Si algo es importante y tiene muchos datos, el mejor canal suele ser…","ops":["Un mensaje escrito, claro y ordenado","Un audio largo","Un comentario de pasillo"],"correcta":0,"explica":"Lo escrito se puede releer y consultar después."}]},{"tipo":"completar","rotulo":"Completa con el elemento que falta","items":[{"frase":"Quien recibe e interpreta el mensaje es el ___.","resp":["receptor"]},{"frase":"Todo lo que distorsiona el mensaje se llama ___.","resp":["ruido"]},{"frase":"WhatsApp, el correo y la llamada son distintos tipos de ___.","resp":["canal","canales"]},{"frase":"La respuesta que confirma si te entendieron es la ___.","resp":["retroalimentacion","retroalimentación"]}]},{"tipo":"reflexion","rotulo":"Un malentendido reciente","pregunta":"Piensa en un malentendido que tuviste en el trabajo o en casa. ¿Qué tipo de ruido hubo? ¿Qué hubieras dicho distinto o por qué canal lo hubieras mandado?","ayuda":"El malentendido fue… El ruido fue… La próxima vez voy a…"},{"tipo":"clave","items":["Comunicar es reducir la distancia entre lo que quisiste decir y lo que el otro entendió.","Hay ruido físico, semántico, psicológico y del canal: nombrarlo ayuda a prevenirlo.","Pide y da retroalimentación: sin ella solo supones que te entendieron."]}],"c-comunicacion-m1-l2":[{"tipo":"texto","texto":"Escuchar no es esperar tu turno para hablar. La <b>escucha activa</b> es poner atención completa, entender lo que el otro quiere decir (no solo sus palabras) y demostrarle que lo entendiste. Es la habilidad de comunicación más subestimada: la gente confía más en quien la escucha que en quien habla bonito."},{"tipo":"pasos","rotulo":"Cinco técnicas de escucha activa","pasos":["<b>Atención completa:</b> deja el celular boca abajo, mira a la persona y no prepares tu respuesta mientras habla.","<b>No interrumpas:</b> deja que termine la idea, aunque creas saber cómo acaba.","<b>Parafrasea:</b> «Entonces, si entendí bien, el problema es que el proveedor entrega tarde los lunes».","<b>Pregunta para aclarar:</b> «¿Cuándo empezó a pasar?», «¿Qué necesitarías de mí?».","<b>Resume y acuerda:</b> «Quedamos en que tú hablas con el proveedor y yo ajusto el turno»."]},{"tipo":"comparar","titulo":"Escuchar o solo oír","malTitulo":"Solo oír","mal":"Compañera: «Estoy muy saturada con los reportes…»<br>Tú (viendo el celular): «Uy, sí, todos. Oye, ¿ya viste lo de la comida del viernes?»","bienTitulo":"Escucha activa","bien":"Compañera: «Estoy muy saturada con los reportes…»<br>Tú (dejando el celular): «Suena pesado. ¿Cuáles te están quitando más tiempo? A lo mejor puedo ayudarte con alguno.»"},{"tipo":"texto","texto":"Sobre el <b>lenguaje no verbal</b> circulan muchos mitos. El más famoso es que «el 93% de la comunicación es no verbal» (la supuesta regla <b>7-38-55</b>: 7% palabras, 38% tono y 55% expresión). Esos números salen de experimentos de <b>Albert Mehrabian</b> en los años sesenta, hechos en un contexto muy limitado: personas que escuchaban <b>palabras sueltas</b> sobre sentimientos, dichas con un tono o un gesto que <b>no coincidía</b>. El propio Mehrabian ha aclarado que no aplica a cualquier conversación. Si fuera cierto, entenderías el 93% de una película en un idioma que no hablas."},{"tipo":"destacado","texto":"<b>Lo que sí sabemos:</b> el tono, la cara y la postura influyen mucho en cómo se recibe un mensaje, sobre todo cuando se trata de emociones o cuando no coinciden con las palabras. Pero <b>ningún gesto significa lo mismo siempre</b>. Cruzar los brazos puede ser frío, comodidad o que la oficina está helada. No existe un «detector de mentiras» por la mirada. Lee el conjunto, el contexto y los cambios, y ante la duda, pregunta."},{"tipo":"practica","rotulo":"¿Mito o realidad?","preguntas":[{"p":"«El 93% de lo que comunicas es no verbal, en cualquier conversación.»","ops":["Realidad comprobada en todos los contextos","Realidad solo en juntas de trabajo","Mito: viene de estudios con palabras sueltas y mensajes contradictorios"],"correcta":2,"explica":"Mehrabian estudió un caso muy específico; no es una regla general."},{"p":"«Si alguien no te mira a los ojos, seguro está mintiendo.»","ops":["Realidad solo en entrevistas","Mito: puede ser timidez, costumbre, cultura o nervios","Realidad: es la señal más confiable"],"correcta":1,"explica":"No hay un gesto que delate mentiras de forma segura."},{"p":"«Si tus palabras dicen una cosa y tu tono otra, la gente suele creerle más al tono.»","ops":["Realidad, sobre todo cuando se habla de emociones","Mito total","Solo pasa por teléfono"],"correcta":0,"explica":"Este es justamente el caso que estudió Mehrabian."},{"p":"«Los brazos cruzados siempre significan rechazo.»","ops":["Realidad universal","Realidad solo en mujeres","Mito: depende del contexto y de la persona"],"correcta":2,"explica":"Puede ser frío, comodidad o costumbre."}]},{"tipo":"completar","rotulo":"Completa la frase de escucha activa","items":[{"frase":"«Entonces, si ___ bien, necesitas el reporte antes de la junta del jueves.»","resp":["entendi","entendí"]},{"frase":"«¿Qué ___ de mí para que esto funcione?»","resp":["necesitas","necesitarias","necesitarías"]},{"frase":"«Quedamos en que tú llamas al cliente y yo mando la ___ por correo.»","resp":["cotizacion","cotización","propuesta","informacion","información"]}]},{"tipo":"clave","items":["Escucha activa: atención completa, no interrumpir, parafrasear, preguntar y resumir.","La regla 7-38-55 no aplica a cualquier conversación: Mehrabian la estudió en un contexto muy limitado.","Ningún gesto significa lo mismo siempre: observa el conjunto y, ante la duda, pregunta."]}],"c-comunicacion-m1-l3":[{"tipo":"texto","texto":"Ante una situación incómoda (un compañero que siempre te deja su trabajo, un cliente que te grita, un jefe que te cambia las prioridades), hay tres formas de responder. La <b>pasiva</b> calla o cede para evitar el conflicto, aunque luego acumule enojo. La <b>agresiva</b> defiende lo propio pasando por encima del otro: gritos, sarcasmo, acusaciones. La <b>asertiva</b> expresa lo que piensas, sientes y necesitas con claridad y respeto, sin atacar y sin dejarte."},{"tipo":"tabla","titulo":"Los tres estilos","encabezados":["Estilo","Cómo suena","Lo que provoca"],"filas":[["Pasivo","«No, no pasa nada…», «Como tú digas», «Lo que sea está bien»","Te aprovechan, acumulas resentimiento, nadie sabe qué necesitas"],["Agresivo","«Siempre haces lo mismo», «¿Qué no entiendes?», «A mí no me vengas con eso»","La otra persona se defiende, se rompe la confianza, el problema no se resuelve"],["Asertivo","«Cuando pasa esto, me afecta así; te propongo esto otro»","Se habla del problema, no de la persona, y hay más probabilidad de acuerdo"]],"nota":"Existe también el estilo pasivo-agresivo: decir «no, no estoy enojado» y luego no contestar mensajes o hacer indirectas. Es de los que más daño hacen en un equipo."},{"tipo":"comparar","titulo":"Un compañero te vuelve a dejar su parte del reporte","malTitulo":"Pasivo o agresivo","mal":"Pasivo: «Ah, sí, no te preocupes, yo lo hago» (y te quedas dos horas extra, molesto).<br>Agresivo: «Otra vez tú de flojo. Ya estoy harto de hacerte la chamba.»","bienTitulo":"Asertivo","bien":"«Beto, es la tercera semana que me toca terminar tu parte del reporte y me estoy quedando tarde. Necesito que cada quien entregue lo suyo el jueves. ¿Qué te está impidiendo terminarlo a tiempo?»"},{"tipo":"plantilla","rotulo":"Fórmula asertiva en cuatro partes","texto":"Cuando [hecho concreto, sin adjetivos],\nme [cómo te afecta o cómo te sientes],\nporque [por qué es importante para ti o para el trabajo].\nTe propongo / te pido [petición concreta y posible].\n\nEjemplo:\nCuando me mandas los cambios después de las 8 de la noche,\nme cuesta tenerlos listos para la mañana,\nporque ya no estoy conectada.\nTe pido que, si hay cambios, me los mandes antes de las 6.","nota":"Habla de hechos, no de la persona: «llegaste 20 minutos tarde» en lugar de «eres un impuntual». Evita «siempre» y «nunca»."},{"tipo":"practica","rotulo":"¿Qué estilo es?","preguntas":[{"p":"«No, está bien, yo me quedo el sábado… como siempre.»","ops":["Agresivo","Pasivo (con un toque pasivo-agresivo)","Asertivo"],"correcta":1,"explica":"Cede y lanza una indirecta en lugar de decir lo que necesita."},{"p":"«Prefiero no quedarme el sábado porque ya tengo un compromiso familiar. Puedo quedarme el siguiente.»","ops":["Asertivo","Pasivo","Agresivo"],"correcta":0,"explica":"Dice que no con respeto y ofrece una alternativa."},{"p":"«¿Otra vez yo? ¿Qué no ven que aquí nadie hace nada más que yo?»","ops":["Asertivo","Pasivo","Agresivo"],"correcta":2,"explica":"Generaliza y ataca; el problema real queda escondido."},{"p":"Tu jefe te pide algo imposible para hoy y respondes: «Hoy puedo entregar la parte A; la B estaría lista mañana a mediodía. ¿Cuál es más urgente?»","ops":["Agresivo","Asertivo","Pasivo"],"correcta":1,"explica":"Negociar prioridades es asertivo."}]},{"tipo":"ordenar","rotulo":"Ordena la frase asertiva","items":[{"frase":"Cuando llegas tarde a la junta, perdemos los primeros acuerdos.","es":"Hecho y consecuencia, sin atacar"},{"frase":"Te pido que me avises si no vas a llegar.","es":"Una petición concreta"},{"frase":"Prefiero no hacerlo hoy, pero puedo mañana temprano.","es":"Decir que no con alternativa"}]},{"tipo":"completar","rotulo":"Cambia la frase agresiva por una asertiva","items":[{"frase":"En lugar de «Nunca contestas», di: «Te mandé tres mensajes ayer y no tuve ___».","resp":["respuesta"]},{"frase":"En lugar de «Eres un desordenado», di: «Cuando las herramientas quedan en el piso, perdemos ___ buscándolas».","resp":["tiempo"]},{"frase":"En lugar de «Haz lo que quieras», di: «Yo ___ la opción B porque es más barata».","resp":["prefiero","propongo","recomiendo","sugiero"]}]},{"tipo":"clave","items":["Pasivo calla, agresivo ataca, asertivo dice lo que necesita con respeto.","Fórmula: cuando (hecho), me (efecto), porque (razón), te pido (petición concreta).","Habla del hecho, no de la persona; evita «siempre» y «nunca»."]}],"c-comunicacion-m2-l1":[{"tipo":"texto","texto":"Casi todas las personas se ponen nerviosas al hablar frente a un grupo, incluso quienes lo hacen seguido. Los nervios no son el enemigo: son tu cuerpo preparándose (el corazón late rápido, sudan las manos, se seca la boca). La meta no es dejar de sentirlos, sino que <b>no te controlen</b>. Y la mejor medicina contra los nervios es la preparación: es mucho más fácil estar tranquilo cuando sabes exactamente qué vas a decir y en qué orden."},{"tipo":"pasos","rotulo":"Técnicas que sí funcionan antes y durante","pasos":["<b>Ensaya en voz alta</b>, no solo en tu cabeza. Mínimo tres veces, idealmente una frente a alguien o grabándote con el celular.","<b>Apréndete de memoria solo la primera y la última frase.</b> Lo de en medio, con tus palabras y apoyado en tus notas.","<b>Respira lento antes de empezar:</b> inhala contando hasta cuatro y exhala contando hasta seis, varias veces. Exhalar más largo ayuda a bajar la agitación.","<b>Llega temprano:</b> prueba el proyector, el micrófono y el enlace de la videollamada. Muchos nervios vienen de lo técnico.","<b>Busca caras amigables</b> en el público y háblales a ellas al principio.","<b>Haz pausas.</b> Un silencio de dos segundos se siente eterno para ti, pero al público le da tiempo de entender.","<b>Si te trabas, sigue.</b> Nadie conoce tu guion: casi nadie nota el error si tú no lo haces notar."]},{"tipo":"destacado","texto":"<b>La estructura de tres partes</b> sirve para una junta de 5 minutos o una presentación de 30.<br><b>Apertura:</b> captas la atención y dices de qué vas a hablar y por qué les importa.<br><b>Desarrollo con tres ideas:</b> no más de tres puntos principales, cada uno con un dato o ejemplo.<br><b>Cierre:</b> resumes en una frase y dices qué esperas que hagan (decidir, aprobar, probar algo)."},{"tipo":"comparar","titulo":"La apertura de una presentación sobre el nuevo horario","malTitulo":"Apertura que apaga","mal":"«Buenos días… eh… bueno, me pidieron que les platicara de lo del horario… a ver si funciona esto… bueno, empiezo.»","bienTitulo":"Apertura que atrapa","bien":"«El mes pasado tuvimos 38 horas extra solo en el turno de la tarde. Hoy les propongo un cambio de horario que las reduce a la mitad sin contratar a nadie. Son tres cambios y les tomo cinco minutos.»"},{"tipo":"ordenar","rotulo":"Ordena las partes de una exposición","items":[{"frase":"Apertura, tres ideas y cierre con petición concreta","es":"La estructura básica"},{"frase":"Primero di de qué hablarás y por qué importa","es":"Lo que hace una buena apertura"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para bajar los nervios antes de hablar, lo más útil es…","ops":["Ensayar en voz alta varias veces","Memorizar palabra por palabra toda la presentación","No pensar en la presentación hasta el momento"],"correcta":0,"explica":"Memorizar todo aumenta el riesgo de quedarte en blanco si pierdes una palabra."},{"p":"¿Cuántas ideas principales conviene tener en una exposición corta?","ops":["Diez, para que se vea completa","Una por cada diapositiva","Tres o menos"],"correcta":2,"explica":"El público recuerda pocas ideas; mejor tres bien explicadas."},{"p":"El cierre de una presentación debe…","ops":["Agregar un tema nuevo","Resumir y decir qué esperas que haga el público","Terminar con «bueno, es todo»"],"correcta":1,"explica":"Un cierre sin petición deja al público sin saber qué sigue."},{"p":"Si te trabas a la mitad de una frase, lo mejor es…","ops":["Hacer una pausa, retomar y seguir","Pedir disculpas varias veces","Empezar desde el principio"],"correcta":0,"explica":"Casi nadie nota el error si tú no lo haces notar."}]},{"tipo":"completar","rotulo":"Completa las técnicas","items":[{"frase":"Apréndete de memoria la primera y la ___ frase.","resp":["ultima","última"]},{"frase":"Al respirar para calmarte, la exhalación debe ser más ___ que la inhalación.","resp":["larga","lenta"]},{"frase":"Llega ___ para probar el proyector y el micrófono.","resp":["temprano","antes"]}]},{"tipo":"clave","items":["Los nervios son normales; la preparación es lo que los mantiene bajo control.","Estructura: apertura que diga por qué importa, tres ideas con ejemplos y cierre con petición.","Ensaya en voz alta, respira lento y, si te trabas, sigue adelante."]}],"c-comunicacion-m2-l2":[{"tipo":"texto","texto":"Un <b>pitch</b> es una presentación muy corta y convincente: de ti mismo en una entrevista o evento, de una idea en la junta o de tu producto a un cliente. En un minuto caben unas <b>130 a 150 palabras</b> habladas con calma. No es para decirlo todo: es para que la otra persona quiera saber más."},{"tipo":"plantilla","rotulo":"Pitch personal de un minuto","texto":"Hola, soy [nombre] y me dedico a [lo que haces, en palabras sencillas].\n\nAyudo a [a quién] a [resultado concreto]. Por ejemplo, [un logro con un número: redujimos, vendimos, organizamos…].\n\nLo que me distingue es [una fortaleza real, con un ejemplo breve].\n\nAhora estoy buscando [lo que quieres: empleo, clientes, apoyo para un proyecto], y me encantaría [siguiente paso: platicar 15 minutos, mandarte mi propuesta].","nota":"Dilo en voz alta con cronómetro. Si pasas de 70 segundos, recorta adjetivos, no datos."},{"tipo":"comparar","titulo":"Pitch en una entrevista","malTitulo":"Lista de datos sin gancho","mal":"«Pues estudié administración, luego trabajé en varias empresas, hice de todo un poco, soy responsable, puntual, trabajo bajo presión y en equipo…»","bienTitulo":"Pitch con dirección","bien":"«Soy Mariana, llevo cinco años en compras. En mi último trabajo renegocié con tres proveedores y bajamos 12% el costo del empaque. Me gusta ordenar procesos, y por eso me interesó esta vacante: ustedes están abriendo dos sucursales y van a necesitar compras bien controladas.»"},{"tipo":"texto","texto":"Las personas recuerdan mejor las historias que las listas de datos. El <b>storytelling</b> en el trabajo no es inventar cuentos: es contar un caso real con una estructura sencilla. <b>Situación</b> (quién y dónde), <b>problema</b> (qué salió mal o qué estaba en juego), <b>acción</b> (qué se hizo) y <b>resultado</b> (qué cambió, idealmente con un dato). Una historia de 40 segundos puede convencer más que diez diapositivas."},{"tipo":"ordenar","rotulo":"Ordena la estructura de una historia","items":[{"frase":"Situación, problema, acción y resultado","es":"Los cuatro pasos"},{"frase":"Termina con un dato que muestre el cambio","es":"Un buen final"}]},{"tipo":"relacionar","rotulo":"Relaciona cada frase con su parte de la historia","pares":[["«Era diciembre y la tienda de Tlalnepantla tenía filas de 40 minutos»","Situación"],["«Los clientes se iban sin comprar y las quejas se duplicaron»","Problema"],["«Abrimos una segunda caja rápida solo para pagos con tarjeta»","Acción"],["«La espera bajó a 12 minutos y las quejas volvieron a lo normal»","Resultado"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En un minuto de pitch caben aproximadamente…","ops":["Unas 500 palabras","Solo 20 palabras","Entre 130 y 150 palabras habladas con calma"],"correcta":2,"explica":"Por eso hay que elegir lo más importante."},{"p":"El objetivo de un pitch es…","ops":["Impresionar con palabras difíciles","Que la otra persona quiera saber más","Decir todo tu currículum"],"correcta":1,"explica":"Termina con una invitación a un siguiente paso."},{"p":"El storytelling en el trabajo consiste en…","ops":["Contar un caso real con situación, problema, acción y resultado","Inventar historias emocionantes","Leer cuentos al inicio de las juntas"],"correcta":0,"explica":"La historia debe ser verdadera y relacionada con tu mensaje."}]},{"tipo":"reflexion","rotulo":"Tu primera versión","pregunta":"Escribe tu pitch personal usando la plantilla. Luego léelo en voz alta con el cronómetro del celular. ¿Cuánto tardaste? ¿Qué quitarías?","ayuda":"Soy… Me dedico a… Por ejemplo… Busco…"},{"tipo":"clave","items":["Un pitch dura cerca de un minuto (130 a 150 palabras) y termina con un siguiente paso.","Una historia real con situación, problema, acción y resultado se recuerda más que una lista.","Recorta adjetivos, no datos: un número concreto convence más que «soy muy responsable»."]}],"c-comunicacion-m2-l3":[{"tipo":"texto","texto":"Las preguntas del público no son un ataque: son una señal de que te pusieron atención. Aun así, hay preguntas incómodas: alguien que te contradice, una pregunta cuya respuesta no sabes o un comentario que en realidad es un discurso. Para todas sirve la misma base: <b>escucha completa, pausa, respuesta breve y regreso a tu mensaje</b>."},{"tipo":"tabla","titulo":"Qué hacer con cada tipo de pregunta","encabezados":["Situación","Qué hacer"],"filas":[["No sabes la respuesta","Dilo con honestidad y comprométete: «No tengo ese dato; te lo mando hoy antes de las 5»."],["Te contradicen","Agradece, reconoce lo válido y explica tu razón: «Es buen punto; lo consideramos y elegimos esto porque…»."],["La pregunta es confusa","Parafrasea: «¿Tu pregunta es si el cambio aplica también a sucursales?»."],["Alguien se extiende en un discurso","Busca la pregunta: «Entiendo tu preocupación por los costos; ¿tu pregunta es cuánto cuesta el cambio?»."],["La pregunta está fuera de tema","Ofrece verla después: «Buena pregunta; la vemos al terminar para no quitarle tiempo al grupo»."]],"nota":"Nunca inventes una respuesta: si luego se descubre, pierdes la confianza de todo el grupo."},{"tipo":"practica","rotulo":"¿Cómo respondes?","preguntas":[{"p":"Te preguntan un dato que no traes.","ops":["Inventas un número aproximado","«Esa pregunta no viene al caso.»","«No lo tengo a la mano; se lo envío hoy por correo.»"],"correcta":2,"explica":"Honestidad más compromiso con fecha."},{"p":"Un compañero dice en la junta: «Eso ya lo intentamos y no funcionó».","ops":["Ignorarlo y seguir","«Gracias, ¿qué fue lo que falló esa vez? Nos sirve para no repetirlo.»","«Pues esta vez sí va a funcionar.»"],"correcta":1,"explica":"Convierte la objeción en información útil."},{"p":"Alguien lleva tres minutos hablando sin preguntar nada concreto.","ops":["Parafrasear su preocupación y preguntarle cuál es su duda concreta","Interrumpirle con «ya entendimos»","Dejar que siga hasta que termine el tiempo"],"correcta":0,"explica":"Así respetas a la persona y al resto del grupo."}]},{"tipo":"texto","texto":"Las diapositivas son un apoyo, no tu guion. El error más común es llenarlas de texto y leerlas de espaldas al público: la gente lee más rápido de lo que tú hablas y deja de escucharte. Una buena diapositiva tiene <b>una sola idea</b>, pocas palabras, letra grande y, si se puede, una imagen o una gráfica sencilla."},{"tipo":"comparar","titulo":"La misma diapositiva","malTitulo":"Diapositiva que estorba","mal":"Título: «Resultados»<br>Doce renglones de texto en letra 14, tres colores de fuente, un párrafo copiado del informe y una tabla con 40 celdas.","bienTitulo":"Diapositiva que ayuda","bien":"Título: «Las quejas bajaron 35% en tres meses»<br>Una gráfica de barras con tres meses y el número grande en el último. Tú explicas el resto en voz alta."},{"tipo":"lista","items":["<b>Un título que diga la conclusión</b>, no solo el tema: «Las ventas subieron 8%» en lugar de «Ventas».","<b>Máximo 3 a 5 renglones cortos</b> por diapositiva.","<b>Letra grande</b> (que se lea desde el fondo de la sala o en la pantalla del celular en una videollamada).","<b>Contraste alto:</b> letra oscura en fondo claro o al revés.","<b>Una idea por diapositiva.</b> Si tienes dos ideas, haz dos diapositivas."]},{"tipo":"completar","rotulo":"Completa las reglas de las diapositivas","items":[{"frase":"Una buena diapositiva tiene una sola ___.","resp":["idea"]},{"frase":"El título debe decir la ___, no solo el tema.","resp":["conclusion","conclusión"]},{"frase":"Si no sabes una respuesta, no la ___: comprométete a enviarla.","resp":["inventes"]}]},{"tipo":"clave","items":["Ante preguntas difíciles: escucha, pausa, responde breve y regresa a tu mensaje.","Si no sabes algo, dilo y comprométete con una fecha; nunca inventes.","Diapositivas: una idea, pocas palabras, letra grande y título con la conclusión."]}],"c-comunicacion-m3-l1":[{"tipo":"texto","texto":"Un correo con faltas de ortografía puede hacer que el lector dude de todo lo demás, aunque tu propuesta sea excelente. La buena noticia es que la mayoría de los errores se repiten siempre en las mismas palabras. Empecemos por la <b>tilde diacrítica</b>: un acento que no sigue las reglas generales y que sirve para distinguir dos palabras que se escriben igual pero significan cosas distintas."},{"tipo":"tabla","titulo":"Los diacríticos que más se usan en el trabajo","encabezados":["Con tilde","Sin tilde"],"filas":[["<b>tú</b> (pronombre): «¿Tú mandas el reporte?»","<b>tu</b> (posesivo): «Tu reporte llegó.»"],["<b>él</b> (pronombre): «Él lo autorizó.»","<b>el</b> (artículo): «El jefe lo autorizó.»"],["<b>mí</b> (pronombre): «Mándamelo a mí.»","<b>mi</b> (posesivo): «Es mi turno.»"],["<b>sí</b> (afirmación o pronombre): «Sí, voy.» «Lo quiere para sí.»","<b>si</b> (condición): «Si llueve, lo cambiamos.»"],["<b>más</b> (cantidad): «Necesito más tiempo.»","<b>mas</b> (equivale a «pero», casi no se usa)"],["<b>sé</b> (de saber o ser): «No sé si llegue.»","<b>se</b> (pronombre): «Se canceló la junta.»"],["<b>dé</b> (de dar): «Que me dé la factura.»","<b>de</b> (preposición): «La factura de marzo.»"],["<b>té</b> (la bebida)","<b>te</b> (pronombre): «Te llamo mañana.»"],["<b>qué, cuál, cuándo, dónde, cómo, quién</b> en preguntas y exclamaciones","<b>que, cual, cuando…</b> en las demás frases"]],"nota":"Según la Ortografía de la RAE de 2010, «solo» y los demostrativos (este, ese, aquel) se escriben sin tilde. En 2023 la RAE aclaró que quien escribe puede ponerle tilde a «solo» cuando la frase se preste a confusión."},{"tipo":"practica","rotulo":"¿Cuál está bien escrita?","preguntas":[{"p":"Elige la correcta:","ops":["¿Tu ya enviaste tú reporte?","¿Tu ya enviaste tu reporte?","¿Tú ya enviaste tu reporte?"],"correcta":2,"explica":"Tú (pronombre) lleva tilde; tu (posesivo) no."},{"p":"Elige la correcta:","ops":["Si me confirmas, te mando mas información.","Si me confirmas, te mando más información.","Sí me confirmas, té mando mas información."],"correcta":1,"explica":"Si condicional sin tilde, te pronombre sin tilde, más de cantidad con tilde."},{"p":"Elige la correcta:","ops":["No sé si él ya firmó el contrato.","No se si el ya firmó el contrato.","No sé sí él ya firmó el contrato."],"correcta":0,"explica":"Sé (saber) y él (pronombre) llevan tilde; si (condición) no."},{"p":"Elige la correcta:","ops":["¿Cuando sale el pedido? Sale cuándo llegue el material.","¿Cuándo sale el pedido? Sale cuándo llegue el material.","¿Cuándo sale el pedido? Sale cuando llegue el material."],"correcta":2,"explica":"Solo lleva tilde el «cuándo» de la pregunta."},{"p":"Elige la correcta:","ops":["Dile a tu jefa que me de la firma a mí.","Dile a tu jefa que me dé la firma a mí.","Dile a tú jefa que me de la firma a mi."],"correcta":1,"explica":"Tu posesivo, dé de dar, mí pronombre."}]},{"tipo":"tabla","titulo":"Los cuatro porqués","encabezados":["Forma","Cuándo se usa","Ejemplo"],"filas":[["<b>por qué</b>","Para preguntar, directa o indirectamente","«¿Por qué se retrasó?» / «No sé por qué se retrasó.»"],["<b>porque</b>","Para dar una causa (responde)","«Se retrasó porque faltó material.»"],["<b>porqué</b>","Es sustantivo: «el motivo». Va con artículo","«Nadie explicó el porqué del retraso.»"],["<b>por que</b>","Preposición + «que»; se puede cambiar por «por el que» o «por la que». Es poco común","«Esa es la razón por que (por la que) renunció.»"]],"nota":"Truco: si puedes poner «el motivo», es porqué. Si preguntas, es por qué. Si respondes, es porque."},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"No me explicaron ___ cambió la fecha.","ops":["por qué","porque","porqué"],"correcta":0,"explica":"Es una pregunta indirecta: «no me explicaron ¿por qué?»."},{"p":"Llegué tarde ___ hubo un choque en el Periférico.","ops":["por qué","porqué","porque"],"correcta":2,"explica":"Da una causa."},{"p":"Queremos entender el ___ de tantas devoluciones.","ops":["porque","porqué","por qué"],"correcta":1,"explica":"Lleva artículo «el» y equivale a «el motivo»."},{"p":"¿___ no se facturó el pedido del lunes?","ops":["Por qué","Porque","Porqué"],"correcta":0,"explica":"Pregunta directa."}]},{"tipo":"reflexion","rotulo":"Tus errores frecuentes","pregunta":"Abre los últimos cinco mensajes de trabajo que escribiste. ¿Encuentras algún tu/tú, si/sí, mas/más o porque/por qué mal usado? Anota cuál se te repite más.","ayuda":"El que más se me repite es… Mi truco para recordarlo será…"},{"tipo":"clave","items":["La tilde diacrítica distingue palabras iguales: tú/tu, él/el, mí/mi, sí/si, más/mas, sé/se, dé/de.","Qué, cuándo, dónde, cómo y quién llevan tilde en preguntas y exclamaciones, también indirectas.","Pregunta: por qué. Causa: porque. «El motivo»: porqué."]}],"c-comunicacion-m3-l2":[{"tipo":"texto","texto":"Hay palabras que suenan igual y se escriben distinto (se llaman <b>homófonas</b>). En los mensajes rápidos de WhatsApp son las que más se equivocan, y en un mensaje de trabajo dan mala imagen. Aquí van las parejas que más se confunden en México, con un truco para cada una."},{"tipo":"tabla","titulo":"Suenan igual, significan distinto","encabezados":["Palabra","Qué es","Truco"],"filas":[["<b>haber</b>","Verbo (va a haber, puede haber, debe haber) o sustantivo («tiene en su haber»)","Si puedes cambiarlo por «existir» o va después de «va a», es haber"],["<b>a ver</b>","Del verbo ver: «veamos»","Si puedes cambiarlo por «veamos», es a ver"],["<b>hay</b>","Del verbo haber: existe, existen","«Hay junta», «no hay material»"],["<b>ahí</b>","Lugar","Si puedes cambiarlo por «en ese lugar», es ahí"],["<b>ay</b>","Expresión de dolor o sorpresa","«¡Ay, se me olvidó!»"],["<b>hecho</b>","Del verbo hacer, o un suceso","«Ya está hecho», «un hecho importante»"],["<b>echo</b>","Del verbo echar","«Te echo la mano», «lo echo al correo»"]]},{"tipo":"completar","rotulo":"Escribe haber o a ver","items":[{"frase":"Mañana va a ___ junta con los proveedores.","resp":["haber"],"es":"¿«Existir» o «veamos»?"},{"frase":"___ si el lunes ya tenemos la respuesta del cliente.","resp":["a ver"],"es":"Equivale a «veamos si…»."},{"frase":"Debe ___ un error en la factura.","resp":["haber"]},{"frase":"Déjame revisar el archivo, ___ qué pasó.","resp":["a ver"]}]},{"tipo":"completar","rotulo":"Escribe hay, ahí, ay o hecho","items":[{"frase":"No ___ lugar en el estacionamiento de la oficina.","resp":["hay"]},{"frase":"Deja las cajas ___, junto a la puerta.","resp":["ahi","ahí"]},{"frase":"¡___, se me olvidó adjuntar el archivo!","resp":["ay"]},{"frase":"¿___ alguna duda sobre el nuevo horario?","resp":["hay"]},{"frase":"Te echo la mano con el inventario; ya está ___ la mitad.","resp":["hecho"],"es":"Del verbo hacer."}]},{"tipo":"tabla","titulo":"Signos y mayúsculas","encabezados":["Regla","Así sí","Así no"],"filas":[["En español las preguntas y exclamaciones abren y cierran","«¿Llegas a las 9?» «¡Felicidades!»","«Llegas a las 9?» «Felicidades!!!»"],["Días, meses y estaciones van con minúscula","«El lunes 3 de marzo»","«El Lunes 3 de Marzo»"],["Cargos y profesiones van con minúscula","«La directora general autorizó»","«La Directora General autorizó»"],["Nombres de instituciones y empresas van con mayúscula","«Instituto Mexicano del Seguro Social»","«instituto mexicano del seguro social»"],["Las mayúsculas también llevan tilde","«ÁREA DE COMPRAS»","«AREA DE COMPRAS»"],["Escribir todo en mayúsculas se lee como un grito","«Recuerden entregar hoy»","«RECUERDEN ENTREGAR HOY»"]]},{"tipo":"practica","rotulo":"¿Cuál está bien escrita?","preguntas":[{"p":"Elige la correcta:","ops":["Nos vemos el Martes 14 de Octubre?","¿Nos vemos el Martes 14 de octubre?","¿Nos vemos el martes 14 de octubre?"],"correcta":2,"explica":"Signo de apertura y días y meses con minúscula."},{"p":"Elige la correcta:","ops":["La gerente de ventas pidió el reporte del banco de méxico.","La gerente de ventas pidió el reporte del Banco de México.","La Gerente de Ventas pidió el reporte del banco de México."],"correcta":1,"explica":"Cargo con minúscula, institución con mayúscula."},{"p":"Elige la correcta:","ops":["¡Gracias por su apoyo!","Gracias por su apoyo!!!","¡Gracias por su apoyo"],"correcta":0,"explica":"La exclamación abre y cierra, y con un signo basta."},{"p":"Elige la correcta:","ops":["ULTIMO DIA DE ENTREGA","ÚLTIMO DIA DE ENTREGA","ÚLTIMO DÍA DE ENTREGA"],"correcta":2,"explica":"Las mayúsculas llevan tilde igual que las minúsculas."}]},{"tipo":"clave","items":["Haber = existir o va después de «va a»; a ver = veamos.","Hay = existe; ahí = en ese lugar; ay = queja o sorpresa.","Signos de apertura siempre; días, meses y cargos con minúscula; las mayúsculas llevan tilde."]}],"c-comunicacion-m3-l3":[{"tipo":"texto","texto":"Escribir claro no es escribir bonito. Es lograr que el lector entienda <b>a la primera</b>, sin releer. En el trabajo casi nadie lee con calma: se lee en el celular, entre otras cosas. Cuatro hábitos cambian por completo tus textos: <b>frases cortas</b> (una idea por frase, idealmente menos de 25 palabras), <b>voz activa</b> (quién hace qué), <b>cero muletillas</b> y <b>ir al grano</b>."},{"tipo":"comparar","titulo":"Voz pasiva y rodeos contra voz activa y directa","malTitulo":"Confuso","mal":"«Por medio del presente se hace de su conocimiento que, derivado de diversas situaciones que se han venido presentando, la entrega de los materiales fue reprogramada por parte del área de logística para una fecha posterior.»","bienTitulo":"Claro","bien":"«Logística cambió la entrega de materiales al jueves 16 porque el proveedor se retrasó.»"},{"tipo":"tabla","titulo":"Rodeos y muletillas que puedes quitar","encabezados":["En lugar de…","Escribe…"],"filas":[["Por medio del presente me permito informarle que…","Le informo que… (o ve directo al punto)"],["Derivado de lo anterior…","Por eso…"],["En el entendido de que…","Siempre que… / Considera que…"],["Llevar a cabo una revisión","Revisar"],["Realizar el pago correspondiente","Pagar"],["A la brevedad posible","Hoy antes de las 5 (una fecha concreta)"],["Sin más por el momento, quedo a sus órdenes para cualquier duda o aclaración","Quedo atento a tus comentarios. (o nada)"]]},{"tipo":"completar","rotulo":"Cambia el rodeo por un verbo directo","items":[{"frase":"«Llevar a cabo una revisión del contrato» es lo mismo que ___ el contrato.","resp":["revisar"]},{"frase":"«Realizar la entrega del pedido» es lo mismo que ___ el pedido.","resp":["entregar"]},{"frase":"«Hacer una comparación de precios» es lo mismo que ___ precios.","resp":["comparar"]},{"frase":"«Dar inicio a la junta» es lo mismo que ___ la junta.","resp":["iniciar","empezar","comenzar"]}]},{"tipo":"ordenar","rotulo":"Ordena la frase en voz activa","items":[{"frase":"Recursos Humanos publicó las vacaciones del próximo año.","es":"Quién hace qué"},{"frase":"El proveedor entregará los empaques el lunes.","es":"Sujeto, acción y fecha"},{"frase":"Ana revisó las facturas y encontró dos errores.","es":"Dos acciones claras"}]},{"tipo":"destacado","texto":"<b>Lenguaje incluyente, sin exagerar.</b> La idea es que nadie se sienta excluido, sin que el texto se vuelva pesado. Lo más práctico es usar <b>palabras que ya incluyen a todas las personas</b>: «el personal» en lugar de «los trabajadores», «quienes asistan» en lugar de «los asistentes», «la dirección» en lugar de «el director», «la clientela». Evita desdoblar en cada frase («los y las compañeros y compañeras que…»), porque cansa. Evita también la «x» y la «@» («compañerxs»): no se pueden pronunciar y los lectores de pantalla que usan personas ciegas no las leen bien."},{"tipo":"practica","rotulo":"¿Cuál es más clara?","preguntas":[{"p":"Para avisar un cambio de horario:","ops":["«Hay cambio de horario, luego les digo.»","«A partir del lunes 6, el horario será de 8:00 a 16:00.»","«Se hace de su conocimiento que a partir de la próxima semana se llevará a cabo una modificación en el horario de labores.»"],"correcta":1,"explica":"Dice qué cambia y desde cuándo."},{"p":"Para una invitación a todo el equipo:","ops":["«Invitamos a todo el personal a la capacitación del viernes.»","«Invitamos a los y las trabajadores y trabajadoras a la capacitación.»","«Invitamos a lxs trabajadorxs a la capacitación.»"],"correcta":0,"explica":"Un colectivo incluye a todas las personas sin volver pesada la frase."},{"p":"Para pedir un documento:","ops":["«Te agradecería mucho si pudieras, en la medida de tus posibilidades, hacerme llegar la factura.»","«Mándame lo de marzo.»","«¿Me mandas la factura de marzo hoy antes de las 3?»"],"correcta":2,"explica":"Petición concreta, con qué y cuándo."}]},{"tipo":"clave","items":["Una idea por frase y, de preferencia, menos de 25 palabras.","Voz activa: quién hace qué y cuándo. Cambia «llevar a cabo una revisión» por «revisar».","Lenguaje incluyente práctico: colectivos como «el personal» o «quienes asistan», sin «x» ni «@»."]}],"c-comunicacion-m4-l1":[{"tipo":"texto","texto":"Tu correo compite con decenas de mensajes en la bandeja de entrada. El lector decide en segundos si lo abre, y al abrirlo, si lo lee completo. Por eso el <b>asunto</b> y el <b>primer renglón</b> son lo más importante: deben decir de qué se trata y qué necesitas. Lo demás es contexto."},{"tipo":"comparar","titulo":"Asuntos de correo","malTitulo":"Asuntos que no dicen nada","mal":"«Hola»<br>«Pendiente»<br>«URGENTE!!!»<br>«Información»<br>(sin asunto)","bienTitulo":"Asuntos que se entienden sin abrir","bien":"«Solicitud: vacaciones del 10 al 14 de noviembre»<br>«Para aprobar hoy: cotización de uniformes»<br>«Minuta junta de ventas 3 de octubre»<br>«Aviso: cambio de proveedor de papelería»"},{"tipo":"pasos","rotulo":"Estructura de un correo profesional","pasos":["<b>Asunto:</b> tipo de mensaje y tema concreto (Solicitud, Aviso, Para aprobar, Seguimiento).","<b>Saludo:</b> «Hola, Laura:» o «Estimada Laura:». En español, después del saludo va dos puntos, no coma.","<b>Primer renglón:</b> qué necesitas o qué informas. Directo.","<b>Contexto breve:</b> solo lo necesario para decidir, en párrafos de dos a cuatro renglones.","<b>Petición concreta:</b> qué, quién y para cuándo.","<b>Cierre y firma:</b> «Gracias. Quedo atento.» Nombre, puesto y teléfono."]},{"tipo":"plantilla","rotulo":"Correo de solicitud","texto":"Asunto: Solicitud: autorización de compra de 3 sillas para recepción\n\nHola, Laura:\n\nTe pido autorizar la compra de 3 sillas para recepción por $4,350 en total.\n\nLas sillas actuales están rotas y los clientes se quedan de pie mientras esperan. Adjunto dos cotizaciones; la más barata es la de Muebles Juárez, con entrega en 5 días.\n\n¿Me confirmas antes del jueves 9 para alcanzar el precio de la cotización?\n\nGracias.\n\nJorge Méndez\nAuxiliar administrativo | Ext. 204","nota":"Adjunta los archivos antes de escribir el texto: así no se te olvidan."},{"tipo":"plantilla","rotulo":"Correo de seguimiento","texto":"Asunto: Seguimiento: autorización de sillas para recepción\n\nHola, Laura:\n\nTe escribo para dar seguimiento a mi correo del lunes 6 sobre la compra de sillas (lo copio abajo).\n\nLa cotización vence este jueves 9. ¿Puedes confirmarme hoy o mañana? Si prefieres, lo vemos en cinco minutos en tu oficina.\n\nGracias.\n\nJorge","nota":"Da seguimiento después de dos o tres días hábiles. Reenvía el mensaje original para que no tengan que buscarlo y di qué pasa si no hay respuesta."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El mejor asunto para pedir permiso de salir temprano es…","ops":["«Hola, una pregunta»","«Solicitud: salir a las 15:00 el viernes 17»","«Permiso»"],"correcta":1,"explica":"Dice qué pides y cuándo, sin abrir el correo."},{"p":"Después de «Estimada Laura» se escribe…","ops":["Dos puntos","Coma","Punto y coma"],"correcta":0,"explica":"En español la norma es «Estimada Laura:»."},{"p":"¿Qué va en el primer renglón del correo?","ops":["La historia completa del problema","Una disculpa por escribir","Lo que necesitas o lo que informas"],"correcta":2,"explica":"El contexto va después."},{"p":"Para dar seguimiento a un correo sin respuesta conviene…","ops":["Escribir «¿¿¿Nadie me va a contestar???»","Esperar dos o tres días hábiles y reenviar el original con una pregunta concreta","Mandar el mismo correo cada hora"],"correcta":1,"explica":"Amable, concreto y con el original a la mano."}]},{"tipo":"completar","rotulo":"Completa el correo","items":[{"frase":"Asunto: ___: cambio de horario a partir del lunes 6","resp":["aviso"]},{"frase":"Hola, Laura: Te pido ___ la compra de 3 sillas por $4,350.","resp":["autorizar","aprobar"],"es":"Una petición directa en el primer renglón."},{"frase":"¿Me confirmas antes del jueves 9? Gracias. Quedo ___.","resp":["atento","atenta","pendiente"]}]},{"tipo":"clave","items":["El asunto dice el tipo de mensaje y el tema: «Solicitud:», «Aviso:», «Para aprobar:».","Primer renglón con lo que necesitas; después el contexto breve y una petición con fecha.","Seguimiento a los dos o tres días hábiles, con el correo original y una pregunta concreta."]}],"c-comunicacion-m4-l2":[{"tipo":"texto","texto":"Todos nos equivocamos. Lo que la gente recuerda no es el error, sino <b>cómo lo manejaste</b>. Una buena disculpa por escrito tiene cuatro partes: <b>reconoces</b> el error sin rodeos, <b>asumes</b> tu parte sin culpar a otros, <b>explicas lo que ya hiciste</b> para corregirlo y dices <b>qué harás para que no se repita</b>. Una mala disculpa se justifica, culpa al sistema o dice «lamento que te hayas sentido así»."},{"tipo":"comparar","titulo":"Te equivocaste en el precio de una cotización","malTitulo":"Disculpa que empeora las cosas","mal":"«Una disculpa si hubo algún malentendido con la cotización, pero el sistema a veces jala precios viejos y nadie nos avisó del cambio.»","bienTitulo":"Disculpa profesional","bien":"«Me equivoqué en la cotización del martes: puse el precio anterior del cable. Le envío la cotización corregida y, como compromiso, respetamos el precio original en este pedido. Desde hoy reviso los precios con la lista actualizada antes de enviar.»"},{"tipo":"ordenar","rotulo":"Ordena las partes de una disculpa","items":[{"frase":"Reconocer, asumir, corregir y evitar que se repita","es":"Las cuatro partes"},{"frase":"Me equivoqué en la fecha de entrega.","es":"Reconocer sin rodeos"}]},{"tipo":"texto","texto":"Dar una <b>mala noticia</b> por escrito (un retraso, un «no» a una solicitud, un aumento de precio) pide lo mismo que en persona: <b>no esconderla</b> al final de un párrafo largo. Di la noticia pronto, explica la razón en una o dos frases, ofrece lo que sí puedes hacer y cierra con el siguiente paso. Si la noticia afecta mucho a la persona (un despido, un problema grave), mejor dila en persona o por llamada y después confírmala por escrito."},{"tipo":"plantilla","rotulo":"Correo con una mala noticia","texto":"Asunto: Retraso en la entrega del pedido 4521\n\nHola, señor Ramírez:\n\nLe escribo para avisarle que su pedido 4521 no llegará el viernes 10 como acordamos. La nueva fecha es el miércoles 15.\n\nEl motivo es que nuestro proveedor de empaques retrasó su entrega una semana.\n\nPara compensarle, podemos:\n1) Enviarle el viernes una entrega parcial con 60 de las 100 piezas, sin costo de envío.\n2) Mantener el pedido completo para el miércoles con 5% de descuento.\n\nLamento el inconveniente. ¿Cuál opción le funciona mejor? Le confirmo el mismo día.\n\nAtentamente,\nPatricia Luna\nEjecutiva de cuenta","nota":"La noticia va en el primer párrafo, la razón en uno o dos renglones y las opciones en una lista."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál es una disculpa profesional?","ops":["«Me equivoqué al enviar el archivo incompleto; aquí va el completo y desde hoy reviso antes de enviar.»","«Lamento que te hayas sentido así.»","«Una disculpa, pero es que me pasaron mal la información.»"],"correcta":0,"explica":"Reconoce, corrige y previene, sin culpar a otros."},{"p":"Al dar una mala noticia por correo, la noticia va…","ops":["Al final, después de explicar todo","En un archivo adjunto","En el primer párrafo"],"correcta":2,"explica":"Esconderla da la impresión de que quieres que no se note."},{"p":"Para un despido o una noticia muy grave, lo mejor es…","ops":["Mandar un correo a todo el equipo","Decirla en persona o por llamada y después confirmarla por escrito","Mandar solo un WhatsApp"],"correcta":1,"explica":"Las noticias graves merecen una conversación."}]},{"tipo":"completar","rotulo":"Completa la disculpa","items":[{"frase":"«Me ___ en el total de la factura; le envío la corregida.»","resp":["equivoque","equivoqué"]},{"frase":"«Desde hoy ___ los precios con la lista actualizada antes de enviar.»","resp":["reviso","revisare","revisaré","verifico","verificare","verificaré"]}]},{"tipo":"clave","items":["Disculpa: reconoce, asume sin culpar, di qué corregiste y cómo evitarás que se repita.","Mala noticia: dila en el primer párrafo, explica en una o dos frases y ofrece opciones.","Las noticias graves se dan en persona o por llamada y luego se confirman por escrito."]}],"c-comunicacion-m4-l3":[{"tipo":"texto","texto":"Un <b>informe breve</b> responde a una pregunta del jefe o del cliente: ¿cómo vamos?, ¿qué pasó?, ¿qué recomiendas? La regla de oro es poner <b>la conclusión primero</b>. Quien lo lee quizá solo lea el primer párrafo, así que ahí debe estar lo esencial. Después van los datos que lo sostienen y al final lo que propones."},{"tipo":"plantilla","rotulo":"Informe breve de una página","texto":"Informe: Quejas de clientes, septiembre\nPara: Gerencia de tienda | De: Ana Torres | Fecha: 2 de octubre\n\n1. Conclusión\nLas quejas bajaron de 48 a 31 (−35%) después de abrir la caja rápida. La mayoría de las que quedan son por falta de producto.\n\n2. Datos principales\n- Quejas por filas: de 27 a 8.\n- Quejas por falta de producto: de 12 a 15.\n- Otras: de 9 a 8.\n\n3. Recomendación\nRevisar el pedido semanal de los 10 productos que más se agotan. Propongo una junta de 20 minutos con compras el martes 7.","nota":"Si el informe pasa de una página, agrega al inicio un resumen de tres renglones."},{"tipo":"texto","texto":"La <b>minuta</b> es el registro de una junta. Su valor está en los <b>acuerdos</b>: qué se decidió, quién lo hace y para cuándo. Sin minuta, cada quien sale de la junta recordando algo distinto. Mándala el mismo día, mientras todos recuerdan lo que se dijo."},{"tipo":"plantilla","rotulo":"Minuta de junta","texto":"Minuta: Junta de ventas\nFecha: jueves 3 de octubre, 10:00 a 10:40\nAsistentes: Laura (gerente), Jorge, Ana, Beto\n\nTemas tratados\n1. Resultados de septiembre.\n2. Promoción de fin de mes.\n\nAcuerdos\n| Qué | Quién | Para cuándo |\n| Enviar reporte de ventas por sucursal | Ana | Lunes 7 |\n| Cotizar lonas para la promoción | Jorge | Miércoles 9 |\n| Autorizar presupuesto de la promoción | Laura | Viernes 11 |\n\nPróxima junta: jueves 10 de octubre, 10:00","nota":"Cada acuerdo lleva un responsable con nombre y una fecha. «Ver lo de las lonas» no es un acuerdo."},{"tipo":"tabla","titulo":"WhatsApp de trabajo: lo que sí y lo que no","encabezados":["Sí","No"],"filas":[["Un solo mensaje completo con todo lo necesario","Diez mensajes sueltos: «Hola», «Oye», «Una pregunta», «¿Estás?»"],["Texto escrito con los datos importantes","Audios largos con indicaciones que luego hay que volver a escuchar"],["Respetar horarios; si es fuera de horario, aclarar «lo ves mañana»","Escribir a las 11 de la noche esperando respuesta inmediata"],["Temas delicados en privado o en llamada","Regañar o corregir a alguien en el grupo"],["Confirmar con un mensaje breve: «Recibido, lo reviso hoy»","Dejar en visto un mensaje de trabajo sin responder"]]},{"tipo":"comparar","titulo":"Pedir un dato por WhatsApp","malTitulo":"Mensaje que interrumpe","mal":"Hola<br>Oye<br>¿Estás?<br>Una pregunta<br>¿Ya tienes lo de ayer?","bienTitulo":"Mensaje completo","bien":"Hola, Beto. ¿Me pasas el total de ventas de ayer de la sucursal Centro? Lo necesito para el reporte de las 12:00. ¡Gracias!"},{"tipo":"relacionar","rotulo":"Relaciona el documento con lo que no puede faltar","pares":[["Informe breve","La conclusión al principio"],["Minuta","Acuerdos con responsable y fecha"],["Correo de seguimiento","El mensaje original y una pregunta concreta"],["WhatsApp de trabajo","Todo en un solo mensaje completo"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En un informe breve, la conclusión va…","ops":["Al principio","Al final, como sorpresa","En un anexo"],"correcta":0,"explica":"Quien lo lee quizá solo lea el primer párrafo."},{"p":"¿Cuál es un acuerdo bien escrito en una minuta?","ops":["«Ver lo de las lonas»","«Se comentó el tema de las lonas»","«Jorge cotiza tres proveedores de lonas para el miércoles 9»"],"correcta":2,"explica":"Qué, quién y para cuándo."},{"p":"Tienes que corregir un error de un compañero. Lo mejor es…","ops":["Mandar una indirecta en el grupo","Decírselo en privado o en llamada","Señalarlo en el grupo de WhatsApp del equipo"],"correcta":1,"explica":"Corregir en público humilla y rompe la confianza."}]},{"tipo":"clave","items":["Informe: conclusión primero, luego datos y al final la recomendación.","Minuta: el mismo día, con acuerdos que digan qué, quién y para cuándo.","WhatsApp de trabajo: un mensaje completo, por escrito, en horario y lo delicado en privado."]}],"c-comunicacion-m5-l1":[{"tipo":"texto","texto":"La <b>retroalimentación</b> es decirle a alguien cómo está funcionando lo que hace, para que lo repita o lo mejore. Mal dada, se siente como ataque; bien dada, es de lo más valioso que puedes regalarle a un compañero. El problema casi nunca es el contenido, sino la forma: comentarios vagos («échale más ganas»), en público o sobre la persona en lugar de sobre lo que hizo."},{"tipo":"pasos","rotulo":"El modelo SCI: situación, comportamiento, impacto","pasos":["<b>Situación:</b> di cuándo y dónde. «En la junta con el cliente de ayer…»","<b>Comportamiento:</b> describe lo que la persona hizo o dijo, algo que se pudo ver u oír, sin adjetivos. «…interrumpiste dos veces al cliente mientras explicaba su problema…»","<b>Impacto:</b> explica el efecto. «…y noté que se molestó y dejó de darnos detalles.»","<b>Pregunta y acuerda:</b> «¿Cómo lo viste tú? ¿Qué te parece si en la próxima tomas notas y hablas al final?»"]},{"tipo":"comparar","titulo":"La misma retroalimentación","malTitulo":"Vaga y personal","mal":"«Oye, eres muy desesperado con los clientes. Échale más ganas.»","bienTitulo":"Con el modelo SCI","bien":"«En la junta de ayer con Grupo Norte interrumpiste dos veces al cliente mientras explicaba el problema, y noté que dejó de darnos detalles. ¿Cómo lo viste tú? En la próxima, ¿te parece si tomas notas y preguntas al final?»"},{"tipo":"destacado","texto":"<b>La retroalimentación positiva también se da con el modelo.</b> «Buen trabajo» se olvida en un minuto. «En el reporte de ayer pusiste la conclusión al principio y la gerente lo aprobó sin preguntas; así hazlos siempre» le dice a la persona exactamente qué repetir. Y recuerda: la positiva se puede dar en público; la de mejora, casi siempre en privado."},{"tipo":"relacionar","rotulo":"Relaciona cada frase con su parte del modelo","pares":[["«El martes, en la entrega de turno…»","Situación"],["«…no anotaste los pendientes en la bitácora…»","Comportamiento"],["«…y el turno de la noche no supo que faltaba el pedido.»","Impacto"],["«¿Qué te parece si usamos una lista de revisión?»","Acuerdo"]]},{"tipo":"tabla","titulo":"Cuando te toca recibirla","encabezados":["En lugar de…","Haz esto"],"filas":[["Justificarte de inmediato: «Es que…»","Escucha completo y respira antes de contestar"],["Atacar de regreso: «Pues tú también…»","Agradece: «Gracias por decírmelo»"],["Quedarte con la duda","Pregunta un ejemplo concreto: «¿Me dices en qué momento lo notaste?»"],["Cambiar todo por un solo comentario","Decide qué aplica y qué no; si varias personas te dicen lo mismo, tómalo en serio"]]},{"tipo":"completar","rotulo":"Completa la retroalimentación","items":[{"frase":"«En la junta de ayer ___ al cliente dos veces mientras hablaba.»","resp":["interrumpiste"]},{"frase":"Cuando recibes una crítica, lo primero es escuchar y decir: «___ por decírmelo».","resp":["gracias"]},{"frase":"La retroalimentación de mejora se da casi siempre en ___.","resp":["privado"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál es un comportamiento bien descrito?","ops":["«Llegaste 20 minutos tarde a las tres juntas de esta semana»","«Eres impuntual»","«No te importa el equipo»"],"correcta":0,"explica":"Algo que se pudo ver, sin adjetivos sobre la persona."},{"p":"Tu jefa te dice que tu último informe tenía errores. La mejor respuesta es…","ops":["«Es que me lo pidieron con muy poco tiempo.»","«Pues el tuyo del mes pasado también tenía errores.»","«Gracias. ¿Me dices cuáles para corregirlos y no repetirlos?»"],"correcta":2,"explica":"Agradecer y pedir ejemplos te ayuda a mejorar."}]},{"tipo":"clave","items":["Modelo SCI: situación, comportamiento (sin adjetivos), impacto, y después un acuerdo.","La positiva también se da con detalle; la de mejora, en privado.","Al recibirla: escucha, agradece, pide ejemplos y decide qué aplicar."]}],"c-comunicacion-m5-l2":[{"tipo":"texto","texto":"Negociar no es ganarle al otro: es encontrar un acuerdo que ambos puedan aceptar. Ya sea pedir un aumento, pactar un plazo con un proveedor o acordar tus días de vacaciones, la conversación se gana <b>antes</b>, en la preparación. Llegar con «pues ya me toca» es muy distinto a llegar con datos, logros y una propuesta."},{"tipo":"pasos","rotulo":"Prepara tu negociación","pasos":["<b>Define qué quieres exactamente:</b> una cantidad o condición concreta, y el mínimo que aceptarías.","<b>Investiga:</b> cuánto se paga por un puesto parecido en bolsas de trabajo y con conocidos del ramo, o cuánto cobra otro proveedor.","<b>Junta tus argumentos:</b> logros con números, nuevas responsabilidades, lo que has aprendido.","<b>Piensa en lo que le importa al otro:</b> presupuesto, carga de trabajo, metas del área.","<b>Ten un plan B:</b> ¿qué harás si la respuesta es no? Pedir otra fecha, otro beneficio o buscar otras opciones.","<b>Elige el momento:</b> pide una cita; no lo hagas en el pasillo ni el día de cierre."]},{"tipo":"comparar","titulo":"Pedir un aumento","malTitulo":"Petición que no convence","mal":"«Oiga, jefe, ya tengo tres años aquí y todo está muy caro. ¿No me podría subir algo?»","bienTitulo":"Petición preparada","bien":"«Quiero hablar de mi sueldo. Desde enero atiendo también la sucursal Norte y bajé los faltantes de inventario de 4% a 1.5%. Revisé vacantes parecidas y el rango está entre 14,000 y 16,000 pesos; yo gano 12,500. Te propongo un ajuste a 15,000. ¿Qué necesitarías ver para aprobarlo?»"},{"tipo":"lista","items":["<b>Habla de tu trabajo, no de tus gastos.</b> Que todo esté caro es verdad, pero no es un argumento de desempeño.","<b>Di una cifra concreta.</b> «Algo más» deja la decisión en el aire.","<b>Escucha la respuesta completa</b> y pregunta: «¿Qué necesitarías ver para aprobarlo?».","<b>Si hay un no</b>, pide un plan: «¿Qué tendría que lograr y en qué fecha lo revisamos?», y confírmalo por correo.","<b>Evita los ultimátums</b> («o me subes o me voy») a menos que de verdad estés dispuesto a irte."]},{"tipo":"ordenar","rotulo":"Ordena la frase de negociación","items":[{"frase":"¿Qué necesitarías ver para aprobar este ajuste?","es":"Pregunta que abre la puerta"},{"frase":"¿Qué tendría que lograr y cuándo lo revisamos?","es":"Si la respuesta es no"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El mejor argumento para pedir un aumento es…","ops":["Que otro compañero gana más","Tus logros con números y tus nuevas responsabilidades","Que todo está muy caro"],"correcta":1,"explica":"Tu desempeño es lo que la empresa puede justificar."},{"p":"Si te dicen que por ahora no hay presupuesto…","ops":["Pides un plan con metas y fecha de revisión, y lo confirmas por correo","Amenazas con renunciar","Aceptas y no vuelves a tocar el tema"],"correcta":0,"explica":"Un «no por ahora» puede volverse un «sí» con fecha."},{"p":"Tu plan B en una negociación es…","ops":["La cifra más alta que vas a pedir","Una excusa para no negociar","Lo que harás si no llegan a un acuerdo"],"correcta":2,"explica":"Tener una alternativa te da tranquilidad para negociar."}]},{"tipo":"completar","rotulo":"Completa la petición","items":[{"frase":"«Te propongo un ajuste a 15,000 ___ mensuales.»","resp":["pesos"]},{"frase":"«Desde enero bajé los faltantes de inventario de 4% a 1.5%.» Esto es un ___ con número.","resp":["logro","resultado","argumento"]}]},{"tipo":"clave","items":["La negociación se gana en la preparación: qué quieres, datos, argumentos y plan B.","Pide una cifra concreta, apoyada en logros y no en gastos personales.","Si es un no, pide un plan con metas y fecha, y confírmalo por escrito."]}],"c-comunicacion-m5-l3":[{"tipo":"texto","texto":"En una entrevista de trabajo te van a pedir ejemplos: «Cuéntame de una vez que resolviste un problema difícil». Para no divagar, usa el método <b>STAR</b> (por sus siglas en inglés): <b>Situación</b>, <b>Tarea</b> (qué te tocaba a ti), <b>Acción</b> (qué hiciste tú, en primera persona) y <b>Resultado</b> (qué pasó, con un dato si puedes). Prepara tres o cuatro historias así antes de la entrevista y adáptalas a cada pregunta."},{"tipo":"relacionar","rotulo":"Relaciona cada parte de la respuesta con el método STAR","pares":[["«En la tienda de Coyoacán teníamos muchas devoluciones de zapatos»","Situación"],["«Me pidieron encontrar la causa en dos semanas»","Tarea"],["«Revisé 80 devoluciones y vi que la tabla de tallas del sitio estaba mal»","Acción"],["«Corregimos la tabla y las devoluciones bajaron 30% al mes siguiente»","Resultado"]]},{"tipo":"tabla","titulo":"Preguntas frecuentes de entrevista","encabezados":["Pregunta","Qué buscan","Cómo responder"],"filas":[["«Háblame de ti»","Ver si te expresas con orden","Tu pitch de un minuto enfocado en el puesto"],["«¿Cuál es tu mayor debilidad?»","Honestidad y capacidad de mejorar","Una debilidad real y lo que haces para mejorarla"],["«¿Por qué te fuiste de tu último empleo?»","Que no hables mal de nadie","Razón breve y en positivo: lo que buscas ahora"],["«¿Cuánto quieres ganar?»","Si estás dentro de su rango","Un rango investigado: «Entre 14,000 y 16,000, según las prestaciones»"],["«¿Tienes alguna pregunta?»","Interés real","Siempre ten una o dos: «¿Cómo se mide el éxito en este puesto?»"]],"nota":"En México, la Ley Federal del Trabajo (artículo 133) prohíbe a los patrones pedir certificados de no embarazo para contratar. Si te hacen preguntas discriminatorias, tienes derecho a no responderlas."},{"tipo":"lista","items":["<b>Cámara a la altura de los ojos</b> (pon la laptop sobre unos libros) y mira a la cámara cuando hables.","<b>Luz de frente</b>, no detrás de ti: una ventana a tu espalda te deja en sombra.","<b>Prueba el enlace, el audio y la cámara</b> 10 minutos antes.","<b>Silencia tu micrófono</b> cuando no hables en juntas grandes.","<b>Fondo ordenado</b> o desenfocado, y avisa en casa que estarás en llamada.","<b>Habla un poco más lento</b> y haz pausas: el audio llega con retraso."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En el método STAR, la «A» de Acción describe…","ops":["Lo que opinaba tu jefe","Lo que hiciste tú, en primera persona","Lo que hizo tu equipo en general"],"correcta":1,"explica":"Di «yo revisé», no solo «revisamos»."},{"p":"Te preguntan por qué dejaste tu empleo anterior. Lo mejor es…","ops":["Dar una razón breve y en positivo sobre lo que buscas ahora","Contar todo lo malo de tu exjefe","Decir que no quieres hablar de eso"],"correcta":0,"explica":"Hablar mal de otros preocupa al entrevistador."},{"p":"En una videollamada, la cámara debe estar…","ops":["Abajo, apuntando hacia tu barbilla","Apagada siempre","A la altura de tus ojos"],"correcta":2,"explica":"Así parece que miras a la otra persona."}]},{"tipo":"plantilla","rotulo":"Mi plan personal de 30 días","texto":"Semana 1: Escucha y asertividad\n- Parafrasear en al menos una conversación de trabajo al día.\n- Usar la fórmula «cuando, me, porque, te pido» una vez.\n\nSemana 2: Escritura\n- Revisar tu/tú, si/sí, por qué/porque y haber/a ver antes de enviar cada mensaje.\n- Escribir todos los correos con asunto claro y petición con fecha.\n\nSemana 3: Hablar en público\n- Preparar y grabar mi pitch de un minuto.\n- Participar al menos una vez en cada junta con una idea preparada.\n\nSemana 4: Conversaciones importantes\n- Dar una retroalimentación positiva con el modelo SCI.\n- Preparar (con datos) la conversación que tengo pendiente: [aumento, acuerdo o entrevista].\n\nAl día 30: ¿qué cambió? ¿Qué sigo practicando?","nota":"Elige solo dos acciones por semana. Es mejor cumplir poco que planear mucho."},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"¿Cuál es la conversación o el texto que más te cuesta en tu trabajo? Escribe qué vas a hacer distinto la próxima vez, usando algo de este curso.","ayuda":"Lo que más me cuesta es… La próxima vez voy a…"},{"tipo":"clave","items":["Entrevista: responde con STAR (situación, tarea, acción y resultado) y lleva preguntas propias.","Videollamada: cámara a los ojos, luz de frente, prueba previa y hablar con pausas.","Un plan de 30 días con dos acciones por semana convierte lo aprendido en hábito."]}]},"q":{"c-comunicacion-m1":[{"p":"La retroalimentación en la comunicación es…","ops":["El canal por el que viaja el mensaje, como el correo o la voz","El ruido de fondo","La persona que habla","La respuesta que confirma o corrige lo que se entendió"],"correcta":3},{"p":"«Lo reviso al rato» puede generar ruido…","ops":["Técnico","Ningún ruido, porque en México todos entendemos «al rato»","Semántico, porque «al rato» significa cosas distintas","Físico"],"correcta":2},{"p":"Parafrasear consiste en…","ops":["Leer un guion","Repetir con tus palabras lo que entendiste para confirmarlo","Interrumpir para dar tu opinión y así avanzar más rápido en la plática","Cambiar de tema con cortesía"],"correcta":1},{"p":"Sobre la regla 7-38-55 de Mehrabian, lo correcto es…","ops":["Salió de estudios con palabras sueltas y mensajes contradictorios, no aplica a cualquier conversación","Demuestra que las palabras casi no importan: el 93% de lo que comunicamos es tono de voz y lenguaje corporal en cualquier situación","Es una ley válida en toda comunicación","La inventó la RAE"],"correcta":0},{"p":"Si alguien cruza los brazos en una junta…","ops":["Seguro está en contra de ti y de tu propuesta, y conviene confrontarlo","Está mintiendo","Está aburrido","Puede significar varias cosas; conviene ver el contexto"],"correcta":3},{"p":"«Como tú digas, lo que sea está bien» (aunque no estés de acuerdo) es un estilo…","ops":["Pasivo","Asertivo","Agresivo"],"correcta":0},{"p":"¿Cuál frase es asertiva?","ops":["«Ya ni les digo nada, total.»","«Cuando cambian la fecha sin avisar, me cuesta cumplir; les pido que me avisen con un día de anticipación.»","«Ustedes siempre cambian todo sin avisar, qué desorganización; así no se puede trabajar con nadie en esta empresa, de verdad»","«No importa, yo me adapto a lo que sea.»"],"correcta":1},{"p":"En una petición asertiva conviene…","ops":["Hablar de hechos concretos y no de la persona","Usar «siempre» y «nunca» para que la otra persona entienda la gravedad","Evitar decir lo que necesitas","Mandar indirectas"],"correcta":0}],"c-comunicacion-m2":[{"p":"La meta al manejar los nervios es…","ops":["Eliminarlos por completo","Ocultarlos detrás del atril","Hablar más rápido para terminar lo antes posible","Que no te controlen, aunque los sientas"],"correcta":3},{"p":"¿Qué conviene aprenderse de memoria?","ops":["Solo los números","Nada","La primera y la última frase","Toda la presentación palabra por palabra"],"correcta":2},{"p":"La estructura básica de una exposición es…","ops":["Leer las diapositivas en orden","Apertura, tres ideas y cierre con petición","Saludo, chiste y despedida","Diez puntos importantes y una conclusión larga"],"correcta":1},{"p":"Un buen pitch termina con…","ops":["Una invitación a un siguiente paso","Tu fecha de nacimiento","Una lista de adjetivos","Una disculpa por quitarles su tiempo"],"correcta":0},{"p":"La estructura de una historia de trabajo es…","ops":["Inicio, un chiste para romper el hielo y moraleja","Problema, culpa y castigo","Datos, datos y más datos","Situación, problema, acción y resultado"],"correcta":3},{"p":"Si te preguntan un dato que no sabes…","ops":["Cambias de tema","Dices que la pregunta no aplica o está mal planteada","Lo dices con honestidad y te comprometes a enviarlo","Inventas uno aproximado"],"correcta":2},{"p":"Un buen título de diapositiva es…","ops":["«Varios»","«Las quejas bajaron 35% en tres meses»","«Resultados»","«Diapositiva 4: datos de quejas del trimestre»"],"correcta":1},{"p":"El error más común con las diapositivas es…","ops":["Llenarlas de texto y leerlas","Usar letra grande","Poner una sola idea","Usar una gráfica sencilla con pocos datos"],"correcta":0}],"c-comunicacion-m3":[{"p":"¿Cuál frase está bien escrita?","ops":["¿Tu crees que el ya lo sabe, o no?","¿Tú crees que el ya lo sabe?","Tu crees que él ya lo sabe?","¿Tú crees que él ya lo sabe?"],"correcta":3},{"p":"«No entiendo ___ no llegó el pedido.»","ops":["porqué","por que","por qué","porque"],"correcta":2},{"p":"«Va a ___ cambios en el horario.»","ops":["haver","haber","a ver","aver"],"correcta":1},{"p":"«Deja el paquete ___, en recepción.»","ops":["hay","ay","ahí"],"correcta":2},{"p":"¿Cuál está bien escrita?","ops":["La junta es el Jueves 2 de Abril de 2026.","La Junta es el jueves 2 de Abril.","la junta es el Jueves 2 de abril.","La junta es el jueves 2 de abril."],"correcta":3},{"p":"¿Cuál es la versión en voz activa y directa?","ops":["«Se procedió a la cancelación del pedido.»","«Derivado de lo anterior, el pedido quedó cancelado.»","«Compras canceló el pedido por falta de presupuesto.»","«El pedido fue cancelado por parte del área de compras.»"],"correcta":2},{"p":"«Llevar a cabo el pago» se puede escribir de forma más directa como…","ops":["Realizar el pago","Efectuar el pago correspondiente","Pagar"],"correcta":2},{"p":"Una forma práctica de lenguaje incluyente es…","ops":["Usar palabras colectivas como «el personal» o «quienes asistan»","Escribir «compañerxs»","Desdoblar todas las palabras en cada frase del texto («los y las»)","Usar la arroba: «compañer@s»"],"correcta":0}],"c-comunicacion-m4":[{"p":"¿Cuál es el mejor asunto de correo?","ops":["«Pendiente»","«URGENTE!!! Favor de revisar y responder hoy»","«Hola»","«Para aprobar hoy: cotización de uniformes»"],"correcta":3},{"p":"Después del saludo de un correo («Hola, Laura») se escriben…","ops":["Una coma y nada más","Un signo de exclamación","Dos puntos","Tres puntos"],"correcta":2},{"p":"Un buen seguimiento a un correo sin respuesta…","ops":["Se manda al día siguiente con mayúsculas para que lo vean","Reenvía el original y hace una pregunta concreta","Repite el mismo correo cada hora","Reclama en copia a todo el equipo"],"correcta":1},{"p":"Una disculpa profesional incluye…","ops":["Reconocer el error, corregirlo y decir cómo evitarás que se repita","Explicar con detalle por qué fue culpa del sistema y no de nosotros","«Lamento que te hayas sentido así»","Solo la palabra «perdón»"],"correcta":0},{"p":"Al comunicar un retraso por correo, la noticia debe ir…","ops":["Al final del correo","Solo en el asunto","En un archivo adjunto","En el primer párrafo"],"correcta":3},{"p":"En un informe breve, lo primero es…","ops":["Los agradecimientos","La lista de anexos","La conclusión","La historia de la empresa"],"correcta":2},{"p":"Lo más valioso de una minuta son…","ops":["La hora de inicio","Los acuerdos con responsable y fecha","Los chistes de la junta","La lista de temas tratados, aunque no haya acuerdos"],"correcta":1},{"p":"En WhatsApp de trabajo conviene…","ops":["Mandar un solo mensaje completo por escrito","Mandar audios largos con indicaciones","Escribir «¿Estás?» y esperar a que respondan","Corregir a compañeros en el grupo"],"correcta":0}],"c-comunicacion-m5":[{"p":"El modelo SCI para dar retroalimentación significa…","ops":["Saludo, crítica constructiva e insistencia","Sueldo, cargo e incentivo","Sinceridad, calma e ironía","Situación, comportamiento e impacto"],"correcta":3},{"p":"¿Cuál es un comportamiento bien descrito?","ops":["«Nunca te importa nada de lo que te pido, eres muy irresponsable»","«Tienes mala actitud»","«Entregaste el reporte dos días después de la fecha acordada»","«Eres irresponsable»"],"correcta":2},{"p":"Al recibir una crítica, lo más útil es…","ops":["Ignorarla","Escuchar, agradecer y pedir un ejemplo concreto","Justificarte de inmediato","Contraatacar con un error que la otra persona cometió"],"correcta":1},{"p":"El mejor argumento para pedir un aumento es…","ops":["Tus logros medibles y tus nuevas responsabilidades","Que tus gastos subieron","Que llevas mucho tiempo en la empresa sin faltar ni llegar tarde","Que un compañero gana más"],"correcta":0},{"p":"Si en una negociación de aumento te dicen que no por ahora…","ops":["Renuncias de inmediato","No vuelves a tocar el tema para no quedar mal con tu jefe","Hablas mal de la empresa","Pides metas y fecha de revisión y lo confirmas por correo"],"correcta":3},{"p":"El método STAR se usa para…","ops":["Escribir una minuta","Calcular un aumento","Responder preguntas de entrevista con ejemplos ordenados","Diseñar diapositivas con estructura, orden y buena presentación"],"correcta":2},{"p":"En una videollamada conviene…","ops":["Hablar más rápido de lo normal","Poner la cámara a la altura de los ojos y la luz de frente","Tener una ventana detrás de ti","Dejar el micrófono abierto siempre para participar en cualquier momento"],"correcta":1},{"p":"Un buen plan personal de 30 días…","ops":["Tiene pocas acciones concretas por semana","Incluye todo lo del curso desde el primer día","No necesita revisarse al final","Se escribe pero no se aplica"],"correcta":0}]}});
